from collections import Counter

def line_stats(g, thresh=.7):
 h,w=len(g),len(g[0]); colors=set(sum(g,[])); out={}
 for c in colors:
  rs=[i for i,row in enumerate(g) if row.count(c)/w>=thresh]
  cs=[j for j in range(w) if sum(g[i][j]==c for i in range(h))/h>=thresh]
  out[c]=(len(rs),len(cs),rs,cs)
 return out
